const rows = $('Read Paperclip run history').all().map(({ json }) => json);
const runs = rows.flatMap((row) => Array.isArray(row) ? row : Array.isArray(row.runs) ? row.runs : Array.isArray(row.items) ? row.items : row.run ? [row.run] : row.id || row.runId ? [row] : []);
if (runs.length > 1000) throw new Error('Paperclip run history exceeded the 1000-run export limit.');
const iso = (v) => { const d = v ? new Date(v) : null; return d && Number.isFinite(d.getTime()) ? d.toISOString() : null; };
const events = runs.map((run, i) => {
  const id = String(run.id ?? run.runId ?? '');
  const startedAt = iso(run.startedAt ?? run.started_at ?? run.createdAt ?? run.created_at);
  const endedAt = iso(run.endedAt ?? run.finishedAt ?? run.completedAt ?? run.ended_at ?? run.finished_at);
  const raw = String(run.status ?? 'unknown').toLowerCase();
  const map = { succeeded: 'completed', success: 'completed', done: 'completed', completed: 'completed', failed: 'failed', error: 'failed', blocked: 'blocked', cancelled: 'cancelled', canceled: 'cancelled' };
  const status = map[raw] ?? raw;
  const duration = startedAt && endedAt ? Math.max(0, Date.parse(endedAt) - Date.parse(startedAt)) : null;
  return { event_id: `paperclip:${id || `row-${i}`}`, schema_version: '1.0', occurred_at: endedAt ?? startedAt ?? new Date().toISOString(), agent_id: String(run.agentId ?? run.agent_id ?? 'unknown-agent'), task_id: String(run.issueId ?? run.issue_id ?? id ?? `row-${i}`), status, duration_ms: duration, policy_version: null, evidence_refs: id ? [`paperclip-run:${id}`] : [], synthetic: false };
});
return [{ json: { contract: 'faran-event-schema/1.0', source: 'paperclip-local-read-only', company_id: '15af0af3-1b60-4bbb-8dc3-f969c2206ea4', generated_at: new Date().toISOString(), synthetic: false, evidence_status: events.length ? 'real-run-metadata-unverified' : 'connected-no-runs', event_count: events.length, events, changes_made: false, agent_runs_started: false, note: 'Only run metadata is exported. Prompts, issue descriptions, comments, provider traces, credentials, and learner data are excluded.' } }];
